css:
@page { size: A4 landscape; margin: 4mm; }

.print-format {
    margin: 4mm !important; padding: 0 !important;
    page-size: A4; orientation: landscape;
    border-radius: 0 !important; max-width: none !important;
}

.print-format .dor-table td, .print-format .dor-table th { padding: 2px 2px !important; }

.daily-output-record { font-family: 'Arial', sans-serif; font-size: 12px; color: #111; width: 100% !important; margin: 0 !important; }

.dor-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px; }
.dor-hdr-left, .dor-hdr-center, .dor-hdr-right { font-size: 12px; }
.co-name { font-size: 16px; font-weight: bold; }
.doc-title { font-size: 13px; font-weight: bold; margin-top: 2px; }
.dor-divider { margin: 3px 0; }

.section-label { font-weight: bold; font-size: 10px; text-align: center; margin: 5px 0 2px 0; text-transform: uppercase; }

.round-sep { text-align: center; font-size: 9px; color: #999; margin: 7px 0 4px 0; letter-spacing: 3px; }

.dor-table { width: 100%; border-collapse: collapse; border: 1px solid #111; margin-bottom: 5px; table-layout: fixed; }

.dor-table thead tr th { background: #e0e0e0; border: 1px solid #444; text-align: center !important; font-size: 12px; font-weight: bold; }
.dor-table tbody td { border: 1px solid #777; text-align: center !important; font-size: 12px; line-height: 1.15; word-break: break-word; overflow-wrap: break-word; }

.row-lbl-hdr, .row-lbl { width: 42px !important; border-right: 1px solid #111; text-align: left !important; padding-left: 2px !important; font-size: 9px; }
.row-lbl { background: #f0f0f0; font-weight: bold; }

.raw-lbl { width: 42px !important; font-size: 12px !important; font-weight: bold; background: #f0f0f0; }
.raw-cell { font-size: 12px !important; word-break: break-word; }

.rbs-lbl { width: 42px !important; font-size: 12px !important; font-weight: bold; background: #f0f0f0; }
.rbs-cell { font-size: 12px !important; word-break: break-word; }
.qty-cell { font-size: 12px; line-height: 1.15; word-break: break-word; }

.pack-name { font-size: 12px; }
.pack-qty { font-size: 12px; font-weight: bold; }

.decor-th { color: #999; font-weight: bold; font-size: 11px !important; }

.round-th { font-weight: normal !important; font-size: 9px !important; background: #f5f5f5 !important; }
